// POST {"email":"someone@club.org"}
//
// DOES NOT THROW ON BAD INPUT. Throwing here errors the workflow, and with responseMode
// "responseNode" no response node is ever reached — so the caller gets HTTP 200 with an empty
// body and no way to tell what went wrong. Verified against the live webhook (Vhea,
// 2026-09-09). Invalid input is routed to a proper 400 instead.
//
// Lower-cased and trimmed so the mirror lookup, the HubSpot search and the response all speak
// about the same string: addresses arrive from replies, CSV pastes and typed input, and
// "Someone@Club.org " is the same person.
const body = ($json && $json.body) || $json || {};
const raw = String(body.email || '');
const email = raw.trim().toLowerCase();
const valid = !!email && /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
return [{ json: { email, valid, given: raw } }];

parameters.jsonBody:
={{ JSON.stringify({
  filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: $json.email_in }] }],
  properties: ['email','firstname','lastname','company','state','lifecyclestage','hs_lastmodifieddate'],
  limit: 1
}) }}

parameters.jsCode:
// ALWAYS RETURNS ONE ITEM, found or not — same reason as the SQL above. An empty result would
// stop the chain and leave the caller waiting for a response that never comes.
//
// The address searched for is carried through as email_in so the "not found" answer can name it.
const email = $('Prepare the email to search').first().json.email;
const first = ($input.first().json.results || [])[0];

if (!first) {
  return [{ json: { found: false, email_in: email, rows: [] } }];
}

const p = first.properties || {};
const contact = {
  hs_object_id: Number(first.id),
  email: p.email || null,
  firstname: p.firstname || null,
  lastname: p.lastname || null,
  company: p.company || null,
  state: p.state || null,
  lifecyclestage: p.lifecyclestage || null,
  hs_lastmodifieddate: p.hs_lastmodifieddate || null,
  synced_at: new Date().toISOString(),
};

// CACHE WHAT WE JUST PAID FOR. A miss cost an API call; writing it back means the next lookup for
// this person is a local query. Same upsert shape as the sync, so the two can never disagree about
// the row format.
return [{ json: { found: true, email_in: email, contact, rows: [contact] } }];

// WHERE THE TWO BRANCHES MEET. A contact is either already mirrored or was just fetched and
// cached, and from here on the work is identical — so the enrichment is written once rather
// than duplicated down both paths.
//
// "Look in the mirror first" runs on EVERY request, so it can be read directly. "Shape the
// HubSpot result" only runs on the miss branch, and referencing a node that did not execute
// throws — hence the guard rather than an if on some flag.
const pick = fn => { try { return fn(); } catch (e) { return null; } };

const mirror = pick(() => $('Look in the mirror first').first().json) || {};
const fetched = pick(() => $('Shape the HubSpot result').first().json);

let contact = null, source = null;
if (mirror.found) {
  source = 'mirror';
  contact = {
    hs_object_id: Number(mirror.hs_object_id),
    email: mirror.email, firstname: mirror.firstname, lastname: mirror.lastname,
    company: mirror.company, state: mirror.state, lifecyclestage: mirror.lifecyclestage,
    hs_lastmodifieddate: mirror.hs_lastmodifieddate, synced_at: mirror.synced_at,
  };
} else if (fetched && fetched.found) {
  source = 'hubspot';
  contact = fetched.contact;
}

// Unreachable in practice — both inbound branches carry a contact — but returning [] here would
// stop the chain and leave the caller waiting on a response that never comes, which is the one
// failure this workflow must not have.
if (!contact) return [{ json: { found: false, email: mirror.email_in || null } }];

const email = String(contact.email || mirror.email_in || '').toLowerCase();
return [{ json: { found: true, source, contact, contact_id: contact.hs_object_id, email } }];

// v4 batch read answers { results: [ { from: { id }, to: [ { toObjectId, associationTypes } ] } ] }
// One entry per association TYPE, so the same company appears twice when it is both the primary
// and a labelled association. De-duplicated here.
const ids = items => {
  const out = new Set();
  for (const item of items) {
    for (const r of ((item.json || {}).results || [])) {
      for (const t of (r.to || [])) { const n = Number(t.toObjectId); if (Number.isFinite(n)) out.add(n); }
    }
  }
  return [...out];
};

const src = $('Contact to enrich').first().json;
const companyIds = ids($('HubSpot: Companies on this contact').all());
const dealIds = ids($input.all());

// THE SENTINEL IS WHY THERE IS NO IF NODE HERE. A batch read with an empty `inputs` array is a
// 400, and a contact with no deals is the common case, not an edge one. Id 0 cannot exist, so
// HubSpot answers 207 with it listed under `errors` and the real results alongside — which reads
// identically to "none found" and costs one call either way. Branching to avoid it would mean two
// paths converging again before the response, and a node that did not run throws when referenced.
// Batch read takes 100 ids; the heaviest contact in this portal has 25 deals.
const guard = a => (a.length ? a.slice(0, 100).map(String) : ['0']);

return [{ json: {
  contact_id: src.contact_id, email: src.email, source: src.source, contact: src.contact,
  company_ids: companyIds, deal_ids: dealIds,
  company_inputs: guard(companyIds), deal_inputs: guard(dealIds),
} }];

// Into the exact row shape hubspot.hubspot_companies and hubspot.hubspot_deals hold, so the
// on-demand path and the scheduled sync write identical rows and can never disagree about the
// format. Both carry the contact we looked up in associated_contact_ids; the upsert merges it in.
const src = $('Collect the associated ids').first().json;
const cid = Number(src.contact_id);
const now = new Date().toISOString();

// The sentinel id comes back under `errors`, never `results`, so nothing extra has to be filtered.
const results = items => items.flatMap(i => ((i.json || {}).results || []));

const companies = results($('HubSpot: Read those companies').all()).map(r => {
  const p = r.properties || {};
  return {
    hs_object_id: Number(r.id),
    name: p.name || null, domain: p.domain || null, state: p.state || null,
    lifecyclestage: p.lifecyclestage || null,
    associated_contact_ids: [cid],
    hs_lastmodifieddate: p.hs_lastmodifieddate || null, synced_at: now,
  };
});

const deals = results($input.all()).map(r => {
  const p = r.properties || {};
  return {
    hs_object_id: Number(r.id),
    dealname: p.dealname || null, pipeline: p.pipeline || null, dealstage: p.dealstage || null,
    // Empty string is what HubSpot sends for an unset number, and Number('') is 0 — which would
    // invent a zero-value deal rather than record that the amount is unknown.
    amount: (p.amount === '' || p.amount == null) ? null : Number(p.amount),
    closedate: p.closedate || null,
    associated_contact_ids: [cid],
    // Every company this contact is on. A deal reached through the contact is, in practice, a
    // deal at one of their companies, and the resolver needs the company edge for its fallback.
    associated_company_ids: (src.company_ids || []).map(Number),
    hs_lastmodifieddate: p.hs_lastmodifieddate || null, synced_at: now,
  };
});

return [{ json: { companies, deals, contact: src.contact, contact_id: cid, email: src.email, source: src.source } }];

parameters.responseBody:
={{ JSON.stringify((() => {
  const shaped = $('Shape company and deal rows').first().json;
  const resolved = $json || {};
  return {
    found: true,
    source: shaped.source,
    contact: shaped.contact,
    companies: shaped.companies,
    deals: shaped.deals,
    deal_id: resolved.deal_id != null ? Number(resolved.deal_id) : null,
    deal_via: resolved.deal_via || null,
    deal: (shaped.deals || []).find(d => String(d.hs_object_id) === String(resolved.deal_id)) || null,
  };
})()) }}
